import{_ as s,o as e,c as p,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.5智能全物品","description":"","frontmatter":{"translationSource":{"title":"1.5智能全物品","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pRYbuAlRWdRJutvUjeqpKw","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-5-automatic-all-item-production-2"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-5-automatic-all-item-production-2"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-5-automatic-all-item-production-2"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-5-automatic-all-item-production-2"}]]},"headers":[],"relativePath":"zh/1-5-automatic-all-item-production-2.md","filePath":"zh/page-pRYbuAlRWdRJutvUjeqpKw.md"}'),i={name:"zh/1-5-automatic-all-item-production-2.md"};function r(n,a,t,c,d,l){return e(),p("div",null,[...a[0]||(a[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-5智能全物品" aria-hidden="true"></span><h1 id="_1-5智能全物品" tabindex="-1">1.5智能全物品 <a class="header-anchor" href="#_1-5智能全物品" aria-label="Permalink to &quot;1\\.5智能全物品&quot;">​</a></h1><blockquote><p>源页面 ID：<code>pRYbuAlRWdRJutvUjeqpKw</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pRYbuAlRWdRJutvUjeqpKw" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-dsYpLcUvt4sJq232e5MyEh"></span></p><span class="logistics-source-anchor" id="概述" aria-hidden="true"></span><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本基建在 <a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a> 的基础上，调整了武陵主基地布局，并利用剩余空地添加了全物品产出插件。</p><p>基建介绍视频：<a href="https://www.bilibili.com/video/BV1NFe56uEdQ/" target="_blank" rel="noreferrer">【终末地】成熟的基建会自己配平自己 | 1.5智能全物品基建</a></p><div class="callout"><p><span class="mark-red">若有问题请优先观看 </span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a><span class="mark-red"> 文档的常见问题汇总部分，本页面仅会记录全物品基建与原版最大毛产基建的差异部分。</span></p></div><p><strong>言：这里的蓝图没有更新景玉谷和应龙关，请移步原文档安装这两个基地</strong></p><p><span id="source-block-7Q3gAhFm23MJRYikatFJF7"></span></p><span class="logistics-source-anchor" id="蓝图码合集" aria-hidden="true"></span><h2 id="蓝图码合集" tabindex="-1">蓝图码合集 <a class="header-anchor" href="#蓝图码合集" aria-label="Permalink to &quot;蓝图码合集&quot;">​</a></h2><p><span id="source-block-crdHOHmwMpyNJUQmsttjhE"></span></p><span class="logistics-source-anchor" id="开始拍蓝图前" aria-hidden="true"></span><h3 id="开始拍蓝图前" tabindex="-1"><strong>开始拍蓝图前</strong> <a class="header-anchor" href="#开始拍蓝图前" aria-label="Permalink to &quot;**开始拍蓝图前**&quot;">​</a></h3><p><span class="mark-red"><strong>请确认仓储情况：</strong></span></p><p><span class="mark-red">10000+息壤 10000+赤铜块 2000+赤铜零件 1000+紫晶零件 1000+铁制零件 1000+晶体外壳 1000+源矿 500+锦草 500+芽针 500+砂叶种子</span></p><p><span class="mark-red">足量设备</span></p><p><span class="mark-red"><strong>请确认基地升级：</strong></span></p><p><span class="mark-red">建议升满所有的区域扩大和存取线基段（实际上应龙关的存取线可以少点两级），必须开启除了炮台之外所有科技点（部分科技点存在前置任务，查漏补缺请自行完成）</span></p><p><span class="mark-red"><strong>请确认禁区息壤气矿：</strong></span></p><p><span class="mark-red">需要4个矿点以上（80+息壤气/min）的息壤气输送到应龙关基地</span></p><p>以下为选做，完成后基建会自动优化至最大产能：</p><p>建设等级达到24级且连接所有矿点（源矿540 蓝铁矿120 赤铜矿510 息壤气150）</p><p>超库存传输致密源石粉末</p><p>连接净水节点</p><p>将应龙关基地的富余息壤气使用<span class="mark-red">多口暗管</span>输送到武陵主基地（这一步若不做，则雪松林的50息壤气可选择不输送）</p><p><span id="source-block-QY0Y5fLZcAXQZw6AZ3zMN3"></span></p><span class="logistics-source-anchor" id="应龙关分基地-与最大毛产相同" aria-hidden="true"></span><span class="logistics-source-anchor" id="yinglong-pass-sub-base-same-as-maximum-gross-production" aria-hidden="true"></span><h3 id="应龙关分基地-与最大毛产相同" tabindex="-1">应龙关分基地（与最大毛产相同） <a class="header-anchor" href="#应龙关分基地-与最大毛产相同" aria-label="Permalink to &quot;应龙关分基地（与最大毛产相同）&quot;">​</a></h3><p><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-aZli93Lno95jxDGgn1OJj9">1.5智能最大毛产</a></p><p>内容与视频展示相比有更新，摆放方式基本一致，01靠最上边拍，后续注意基段连接/贴边等（通常只有一个可放置位置），暗管位置与视频一致。</p><p><span id="source-block-6auPmRtKBFFwDr1UFYAIKM"></span></p><span class="logistics-source-anchor" id="武陵主基地" aria-hidden="true"></span><h3 id="武陵主基地" tabindex="-1">武陵主基地 <a class="header-anchor" href="#武陵主基地" aria-label="Permalink to &quot;武陵主基地&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-75c2dfaeed515d61.jpeg" alt="15智能全物品"></p><p>《明日方舟：终末地》蓝图 [武陵左上01]分享码EF018OI342Eo515aUI73 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵中上02]分享码EF010819Iu3aoiAIE179 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵右上03]分享码EF0170iU169ea5ueO0Ai 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵右下04]分享码EF01o5u82EOI46o7IieO 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵中下05]分享码EF01A67i0a1U9E2E9ieO 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵左下06]分享码EF01E752iAUOeo183uIa 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵净水]分享码EF01I43oEO5u29975o08 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵全物品补充]分享码EF015i2OU7e4Au13eIoe 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [半速固气灌装]分享码EF01U9eAa1670OO271a8 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [16档震荡发电]分享码EF01o5u82EOI46ooIieO 请复制后前往游戏中使用。</p><p><span id="source-block-4mvcuvXYicHquSbQwATrnY"></span></p><span class="logistics-source-anchor" id="天王坪分基地" aria-hidden="true"></span><span class="logistics-source-anchor" id="tianwangping-sub-base" aria-hidden="true"></span><h3 id="天王坪分基地" tabindex="-1">天王坪分基地 <a class="header-anchor" href="#天王坪分基地" aria-label="Permalink to &quot;天王坪分基地&quot;">​</a></h3><p><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5智能最大毛产</a></p><p>可忽略视频讲解中的“景玉谷03”部分，只按顺序放01、02蓝图即可。更新后入水口位置有变化，惰气口在基建中部右侧（水池在下方的视角）</p><p>原蓝图码（与视频一致，但极端情况可能出bug，<span class="mark-red">建议抄最大毛产的修复版</span>）：</p><p>《明日方舟：终末地》蓝图 [天王坪上01]分享码EF01u28IO543E03oAoOU 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [天王坪下A02]分享码EF018OI342Eo5151UI73 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [天王坪下B03]分享码EF013Eou5428OaUi0579 请复制后前往游戏中使用。（03只有水管）</p><p><span id="source-block-vFGg7G1dpct2EvfCS4tQgI"></span></p><span class="logistics-source-anchor" id="首墩分基地" aria-hidden="true"></span><span class="logistics-source-anchor" id="shoudun-sub-base" aria-hidden="true"></span><h3 id="首墩分基地" tabindex="-1">首墩分基地 <a class="header-anchor" href="#首墩分基地" aria-label="Permalink to &quot;首墩分基地&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-360bc82215d72603.jpeg" alt="15智能全物品"></p><p>《明日方舟：终末地》蓝图 [首墩右01]分享码EF01u28IO543E038AoOU 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [首墩左02]分享码EF01Oe4o17iu9I059oe4 请复制后前往游戏中使用。</p><p><span id="source-block-TWNbjFenQ8jvIjlY3KHizK"></span></p><span class="logistics-source-anchor" id="龙泡泡插件" aria-hidden="true"></span><h4 id="龙泡泡插件" tabindex="-1">龙泡泡插件 <a class="header-anchor" href="#龙泡泡插件" aria-label="Permalink to &quot;龙泡泡插件&quot;">​</a></h4><p>《明日方舟：终末地》蓝图 [一阶段01]分享码EF016u0Iuui10762O83e 请复制后前往游戏中使用。</p><p>放置完成后，建议去主基地关闭2~4台赤铜粉碎机，以及1~2台息壤反应池（关哪个视频最后说了）。以简报中赤铜块与息壤消耗殆尽为标准。</p><p><span class="mark-grey"><em>“如果你的息壤和赤铜没被吸干说明你还没有榨干产线的最后一丝产能。”</em></span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a0deb4f53acf50d3.q90-66ef4d4e985f0e57.webp" alt="15智能全物品"></p><p>《明日方舟：终末地》蓝图 【大龙泡泡加压】分享码EF012UO30A7o187oeIOo 请复制后前往游戏中使用。</p><p><span class="mark-red">20260923 19:00更新：修了大龙泡泡蓝图中，极端情况下可能怎样都跑不满速的bug（如果没出现类似问题可以不换）</span></p><p>摆的有点丑请见谅，<span class="mark-red"><strong>需要外接一个水泵，摆完要检查惰气管道，确认连上了之前蓝图的惰气准入口，首墩的四个惰气最好全采集回来</strong></span>。</p><div class="callout"><p><span class="mark-red">请注意：二阶段商店仅一条满速大龙泡泡不足以搬空最后的100个折金票，解决方案包括但不限于在主基地多补一条满速的小龙泡泡（需要自行关闭赤铜粉碎机/息壤反应池），主基地惰气不够再来一条满速的大龙泡泡了。（也没地方摆了）</span></p><p>如果你觉得这点蚊子腿折金票不要也罢那就不用管。</p><p>详情见：<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-Sp48AHGvwvLIbjxO4OoUeX">1.5智能最大毛产</a> 说明部分</p></div><p>加压比例同小龙泡泡，实际需要120赤铜+60息壤，2:1加压，先前摆过小龙泡泡的直接换就行不需要再次开关机器（如果你其他产物的爆仓情况没有变化的话）。</p><p>空间限制原因无法采用最优的固液气途径，息壤消耗较最佳配比多4.8/min。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-103506a8bfda153f.q90-e80cfaba2d02146f.webp" alt="15智能全物品"></p><p>二阶段如果需要主基地多摆小龙泡泡产线可以参考我的摆法：</p><p>“全物品补充”的设备挪到空地里（耐压罐要惰气不能挪），然后原来的位置补一个小龙泡泡的产线，就<span class="mark-red"><strong>用下面那个没有加压的满速产线，不要加压，加压了反而可能会导致大龙泡泡掉速</strong></span>。然后把六个赤铜粉碎机全关了，如果还不够就再多关1~2台，息壤反应池关多少看个人情况，我关了两台。</p><p>小龙泡泡不满速问题不大，5.5/min就够用，如果你一阶段有富余龙泡泡的话也许还能更少（可以自己对着商店按一下计算器看看需要多少）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9834a5e37e0fc3c7.q90-0a805b790726418d.webp" alt="15智能全物品"></p><p>（以下为根据前瞻节目盯帧配方制作的活动产线，未加压）</p><p>《明日方舟：终末地》蓝图 [满速小龙泡泡]分享码EF018OI342Eo515uUI73 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [满速大龙泡泡]分享码EF01eaA7690i14I0oAi8 请复制后前往游戏中使用。</p><p><span id="source-block-SuCVE0S4vwQLSP738fBHEW"></span></p><span class="logistics-source-anchor" id="更新日志" aria-hidden="true"></span><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><p><span id="source-block-VFp0UKHHaASTk2JVQVaOOM"></span></p><h3 id="_20260923" tabindex="-1">20260923 <a class="header-anchor" href="#_20260923" aria-label="Permalink to &quot;20260923&quot;">​</a></h3><p>补充加压大龙泡泡产线</p><p><span class="mark-red">19:00更新：修了大龙泡泡蓝图中，极端情况下可能怎样都跑不满速的bug（如果没出现类似问题可以不换）</span></p><p><span id="source-block-NRBpIel22Ky9YLQ0mpyTKR"></span></p><h3 id="_20260916" tabindex="-1">20260916 <a class="header-anchor" href="#_20260916" aria-label="Permalink to &quot;20260916&quot;">​</a></h3><p>同步最大毛产的改动，补充加压龙泡泡产线</p><p><span id="source-block-ltwxzAIOVMbag5tadOAFHS"></span></p><h3 id="_20260915" tabindex="-1">20260915 <a class="header-anchor" href="#_20260915" aria-label="Permalink to &quot;20260915&quot;">​</a></h3><p>正式发布</p></div>',1)])])}const m=s(i,[["render",r]]);export{h as __pageData,m as default};
